/// Icons offered in the tool editor's icon picker.
pub const PICKER_ICONS: &[&str] = &[
    "", "terminal", "code", "globe", "database", "activity", "cpu", "file-text", "monitor",
    "folder", "edit", "calculator", "settings", "box", "rocket", "zap", "image", "music",
    "mail", "gamepad", "shield", "link", "heart", "star",
];

pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        let Some(name) = path
            .strip_prefix("icons/")
            .and_then(|p| p.strip_suffix(".svg"))
        else {
            return Ok(None);
        };
        Ok(ICONS
            .iter()
            .find(|(n, _)| *n == name)
            .map(|(_, body)| Cow::Owned(format!("{HEAD}{body}</svg>").into_bytes())))
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        if path.trim_end_matches('/') != "icons" {
            return Ok(Vec::new());
        }
        Ok(ICONS
            .iter()
            .map(|(n, _)| SharedString::from(format!("icons/{n}.svg")))
            .collect())
    }
}

pub fn path(name: &str) -> SharedString {
    format!("icons/{name}.svg").into()
}

/// The `'static` name of a known icon.
pub fn static_name(name: &str) -> Option<&'static str> {
    ICONS.iter().find(|(n, _)| *n == name).map(|(n, _)| *n)
}
